package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	n, _ := strconv.Atoi(scanner.Text())

	a := make([]int, n)
	for i := 0; i < n; i++ {
		scanner.Scan()
		a[i], _ = strconv.Atoi(scanner.Text())
	}

	b := make([]int, n)
	for i := 0; i < n; i++ {
		scanner.Scan()
		b[i], _ = strconv.Atoi(scanner.Text())
	}

	rez := 0
	aSum := 0
	bSum := 0

	for i := 0; i < n; i++ {
		aSum += a[i]
		bSum += b[i]
		if a[i] == 1 && b[i] == 0 {
			rez++
		}
	}

	if aSum > bSum {
		fmt.Println(1)
	} else if rez == 0 || aSum == 0 || (aSum == n && bSum == n) {
		fmt.Println(-1)
	} else {
		val := float64(bSum - aSum + 1) / float64(rez)
		result := math.Ceil(val) + 1
		fmt.Println(int(result))
	}
}

